  const repeat = live.filter(asRepeat), ym = PROC_TODAY.slice(0, 7), depM = live.reduce((s, a) => s + asDepMonth(a, ym), 0);
  const kp = `<div class="kpis k6">${k('Assets', NUM(live.length), `${A.length - live.length} disposed · ${live.filter(a => a.status === 'Allocated').length} allocated · ${live.filter(a => a.status === 'Available').length} available`)}${k('Gross value', INRS(cost), `net book value ${INRS(book)}`)}${k('Net book value by type', Object.keys(byType).length, Object.entries(byType).map(([t, v]) => `${t}: ${INRS(v)}`).join(' · '))}${k('Awaiting my action', NUM(inbox.length), inbox.length ? 'transfers, maintenance, incidents, disposals' : 'nothing pending', inbox.length ? 'amber' : '')}${k('Under maintenance', NUM(um.length), `${tx.maint.filter(m => ['Submitted', 'Assigned'].includes(m.status)).length} open work orders · ${INRS(mcost)} repair cost`, um.length ? 'amber' : '')}${k('Missing / damaged', NUM(miss.length + dmg.length), `${miss.length} missing or lost · ${dmg.length} damaged`, miss.length ? 'red' : dmg.length ? 'amber' : '')}</div>
  <div class="kpis k6">${k('Warranty expiring', NUM(wExp.length), `within ${AM().cfg.warrantyAlertDays} days · ${live.filter(a => asWarranty(a).cls === 'bad').length} expired`, wExp.length ? 'amber' : '')}${k('AMC renewals due', NUM(amcExp.length), `within ${AM().cfg.amcAlertDays} days or expired`, amcExp.length ? 'amber' : '')}${k('Verification', verExp ? PCT(verDone / verExp * 100) : '—', `${camps.length} campaigns · ${unver.length} assets not verified in ${AM().cfg.verifyToleranceDays} days`, unver.length > live.length / 2 ? 'amber' : '')}${k('Repeat-failure assets', NUM(repeat.length), `2+ work orders within ${AM().cfg.maint.repeatDays} days`, repeat.length ? 'red' : '')}${k('Depreciation this month', INRS(depM), `${tx.depPost.length} months posted · last ${tx.depPost.length ? tx.depPost[tx.depPost.length - 1].ym : '—'}`)}${k('Pending registrations', NUM(tx.regTasks.filter(t => t.status === 'Pending').length), 'capital items received through GRN awaiting tagging', tx.regTasks.some(t => t.status === 'Pending') ? 'amber' : '')}</div>`;
  const grp = App.f.group || 'branch', keyOf = a => grp === 'branch' ? asBr(a.branch) : grp === 'type' ? (a.branch ? pcBtype(a.branch) : 'Corporate') : grp === 'group' ? 'Group' : (pcBranch(a.branch) || {})[grp === 'zd' || grp === 'zone' ? 'zone' : 'region'] || 'Corporate';
  const agg = new Map(); A.forEach(a => { const kk = keyOf(a); const o = agg.get(kk) || { key: kk, n: 0, alloc: 0, cost: 0, book: 0, maint: 0, miss: 0, dmg: 0, disp: 0 }; if (a.status === 'Disposed') o.disp++; else { o.n++; o.cost += a.cost; o.book += asDep(a).book; if (a.status === 'Allocated') o.alloc++; if (a.status === 'Under Maintenance') o.maint++; if (['Missing', 'Lost'].includes(a.status)) o.miss++; if (['Damaged', 'Scrap'].includes(a.condition)) o.dmg++; } agg.set(kk, o); });
  const rows = [...agg.values()], T = Object.assign({ key: 'Total' }, ...['n', 'alloc', 'cost', 'book', 'maint', 'miss', 'dmg', 'disp'].map(f => ({ [f]: rows.reduce((s, r) => s + r[f], 0) })));
  const t1 = table('asDashT', [{ h: { branch: 'Branch', type: 'Business type', group: 'Group' }[grp] || (grp === 'rd' || grp === 'region' ? 'Region' : 'Zone'), k: r => r.key, t: 'text' }, { h: 'Assets', k: r => r.n, t: 'num' }, { h: 'Allocated', k: r => r.alloc, t: 'num' }, { h: 'Gross value', k: r => r.cost, t: 'inr' }, { h: 'Net book value', k: r => r.book, t: 'inr' }, { h: 'Under maintenance', k: r => r.maint, t: 'num', rc: r => r.maint ? 'amber' : '' }, { h: 'Missing / lost', k: r => r.miss, t: 'num', rc: r => r.miss ? 'red' : '' }, { h: 'Damaged', k: r => r.dmg, t: 'num' }, { h: 'Disposed', k: r => r.disp, t: 'num' }], rows, { total: T, compact: true, title: 'Assets by ' + grp });
