  const hbar = () => { const o = chartBase(INRS); const ink = cssVar('--ink-2'), grid = cssVar('--grid'); o.indexAxis = 'y'; o.scales = { x: { grid: { color: grid }, border: { display: false }, ticks: { color: ink, font: { size: 11 }, callback: v => INRS(v).replace('.00', '') } }, y: { grid: { display: false }, ticks: { color: ink, font: { size: 11 }, autoSkip: false } } }; return o; };
  mountChart('asC1', () => ({ type: 'bar', data: { labels: topC.map(x => x[0]), datasets: [{ data: topC.map(x => x[1]), backgroundColor: cssVar('--accent') }] }, options: hbar() }));
