  return `${asScanBox()}${kp}${ib}${myCard}<div class="grid2">${card('Net book value by category', `<div class="chart" style="height:${Math.max(180, topC.length * 28 + 40)}px"><canvas id="asC1"></canvas></div>`)}${card('Assets by status', '<div class="chart" style="height:220px"><canvas id="asC2"></canvas></div>')}</div>${card('Assets by ' + ({ branch: 'branch', type: 'business type', group: 'group' }[grp] || 'zone / region'), t1, { right: exportBtns('asDashT', 'as_home'), sub: 'Roll up with “Show by” in the filter bar.' })}`;
