  const hist = `<h4 class="blk">History</h4><div class="tbl-wrap compact"><table class="tbl"><thead><tr><th>When</th><th>Who</th><th>Event</th><th>Detail</th></tr></thead><tbody>${(a.history || []).slice().reverse().map(h => `<tr><td class="nowrap">${tsLabel(h.at)}</td><td>${esc(h.by)}</td><td>${esc(h.action)}</td><td class="wrap small">${esc(h.detail || '')}</td></tr>`).join('')}</tbody></table></div>`;
