async function asFormOk(id) {
  const err = m => { const e = document.getElementById('afErr'); if (e) { e.textContent = m; e.hidden = false; } };
  const o = { rfid: v('af_rfid'), cat: v('af_cat'), sub: v('af_sub'), name: (v('af_name') || '').trim(), brand: v('af_brand'), model: v('af_model'), serial: (v('af_serial') || '').trim(), source: v('af_source'), purchaseDate: v('af_pd'), vendor: v('af_vendor'), poNo: v('af_po'), grnNo: v('af_grn'), invoice: v('af_inv'), cost: +v('af_cost') || 0, tax: +v('af_tax') || 0, capDate: v('af_cap'), warrantyFrom: v('af_w1'), warrantyTo: v('af_w2'), life: +v('af_life') || '', method: v('af_method'), rate: +v('af_rate') || '', residual: +v('af_res') || 0, condition: v('af_cond'), branch: v('af_branch'), dept: v('af_dept'), cc: (v('af_cc') || '').trim(), location: (v('af_loc') || '').trim(), spec: v('af_spec'), remarks: v('af_rem') };
  o.amc = v('af_amcv') ? { vendor: v('af_amcv'), value: +v('af_amcval') || 0, from: v('af_amc1'), to: v('af_amc2'), schedule: v('af_amcs') } : null;
  if (!o.name || !o.purchaseDate || !(o.cost >= 0)) return err('Enter the asset name, purchase date and value.'); if (!o.location) return err('Enter the physical location.');
  const tx = Store.clone(AT()); if (o.serial && tx.assets.some(a => a.id !== id && a.serial && a.serial.toLowerCase() === o.serial.toLowerCase())) return err('Another asset carries this serial number (duplicate tag check).');
  if (!o.cc) o.cc = 'CC-' + (o.branch || 'CORP') + '-' + o.cat; const ph = document.getElementById('af_photo'), dc = document.getElementById('af_docs'); if (ph && ph.files[0]) o.photo = ph.files[0].name; if (dc && dc.files.length) o.docs = [...dc.files].map(f => f.name).join(', ');
  const reason = id ? 'Asset master updated' : 'Registered manually';
  askReason(id ? 'Update asset' : 'Register asset', o.name, async r => {
    if (id === 'new') { const a = Object.assign({ id: 'A' + Date.now().toString(36), tag: asTag(tx, o.branch, o.cat), status: 'Available', custodian: '', custodianName: '', history: [] }, o); asHist(a, 'Registered', `${o.source} · ${r}`); tx.assets.unshift(a); await asSave(tx); audit('Asset Management', 'Asset registered', { new: `${a.tag} · ${a.name} · ${INR(a.cost)}`, reason: r }); closeModal(); toast(a.tag + ' registered.'); asOpen(a.id); }
    else { const a = tx.assets.find(x => x.id === id); const diff = Object.keys(o).filter(k => JSON.stringify(a[k]) !== JSON.stringify(o[k])).map(k => `${k}: ${typeof a[k] === 'object' ? JSON.stringify(a[k]) : a[k]} → ${typeof o[k] === 'object' ? JSON.stringify(o[k]) : o[k]}`).join('; '); Object.assign(a, o); asHist(a, reason, diff.slice(0, 300)); await asSave(tx); audit('Asset Management', 'Asset updated', { old: a.tag, new: diff.slice(0, 400), reason: r }); closeModal(); toast('Asset updated.'); asOpen(a.id); }
  });
}

